static BIAS: [[f64; 7]; MODELS] = [[-0.000378499118990393, -0.00017826446537954726, 0.0005829178396600099, 0.0005843200094261434, 0.0019894801938698326, 0.001240211253594084, -0.0031846357488742203], [-0.00025655179470690265, -0.00018339106877474678, 0.00039276998808387194, 3.1005182761386664e-05, 0.002687054434176172, 0.0025504466581691616, -0.003420822506110498], [-0.00031445840327331024, -0.00022309162937833, 0.0002066356166682098, 5.019828869823464e-05, 0.00187872864824235, 0.0010334573911910602, -0.0030222670893282465], [-0.000199231534430676, 0.00010080730991492159, 0.0007068383447749887, 0.00032730154273908116, 0.003379219351793377, 0.0029612672834102905, -0.0014402145127037822], [-0.0004271314492723501, -0.0001919012063599701, 0.0004834126293431012, 0.0001745004476482354, 0.00267833342625481, 0.0017848139593251578, -0.0027209494894765715], [-0.0002341940708855579, -0.00016669699216091276, 0.0003733014572649813, 0.0009910246158134945, 0.002686193802495826, 0.002684735194797725, -0.003260754002160905], [-0.00026777488720105175, 4.8626988534523625e-05, 0.0005938184965042134, 0.0010026004921674788, 0.002324385155576706, 0.0010918488270685758, -0.0034837105964643927]];

use std::io::{self, BufRead, Write};

struct Decoder {
    history: [[f64; CHANNELS]; TAPS],
    cursor: usize,
    smoothed: [f64; 7],
    started: bool,
}
impl Decoder {
    fn new() -> Self { Self { history: [[0.0; CHANNELS]; TAPS], cursor: 0, smoothed: [0.0; 7], started: false } }
    fn step(&mut self, input: [f64; CHANNELS], model: usize) -> [f64; 7] {
        self.history[self.cursor] = input;
        self.cursor = (self.cursor + 1) % TAPS;
        let mut output = BIAS[model];
        for (tau, kernel) in KERNELS.iter().enumerate() {
            let length = KERNEL_LENGTHS[tau];
            let mut rates = [0.0; CHANNELS];
            for lag in 0..length {
                let row = &self.history[(self.cursor + TAPS - 1 - lag) % TAPS];
                let weight = kernel[lag];
                for (rate, count) in rates.iter_mut().zip(row) { *rate += weight * count; }
            }
            let offset = tau * CHANNELS;
            for (feature, rate) in rates.iter().enumerate() {
                let row = &WEIGHTS[model][offset + feature];
                for (value, coefficient) in output.iter_mut().zip(row) { *value += rate * coefficient; }
            }
        }
        // Causal exponential smoothing; resets on decoder construction.
        let updated = if self.started {
            let mut updated = [0.0f64; 7];
            for (index, value) in output.iter().enumerate() {
                updated[index] = SMOOTH_BETA * value + (1.0 - SMOOTH_BETA) * self.smoothed[index];
            }
            updated
        } else {
            output
        };
        self.smoothed = updated;
        self.started = true;
        updated
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let stdin = io::stdin();
    let mut reader = stdin.lock();
    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());
    let mut line = String::with_capacity(CHANNELS * 24);
    let mut decoder = Decoder::new();
    let mut model = 0;
    loop {
        line.clear();
        if reader.read_line(&mut line)? == 0 { break; }
        if line.trim().is_empty() { continue; }
        if let Some(rest) = line.trim().strip_prefix("reset ") {
            model = rest.parse::<usize>()?;
            if model >= MODELS { return Err("model index out of range".into()); }
            decoder = Decoder::new();
            continue;
        }
        let mut fields = line.split_whitespace();
        let mut counts = [0.0; CHANNELS];
        for count in &mut counts {
            *count = fields.next().ok_or("too few neural channels")?.parse::<f64>()?;
            if !count.is_finite() || *count < 0.0 { return Err("invalid neural count".into()); }
        }
        if fields.next().is_some() { return Err("too many neural channels".into()); }
        let values = decoder.step(counts, model);
        for (index, value) in values.iter().enumerate() {
            if index > 0 { write!(writer, " ")?; }
            write!(writer, "{value:.17}")?;
        }
        writeln!(writer)?;
    }
    writer.flush()?;
    Ok(())
}
